import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_forward(torch::Tensor x,
                                        torch::Tensor weight,
                                        c10::optional<torch::Tensor> bias,
                                        int stride, int padding, int output_padding,
                                        int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T, int KC>
__global__ __launch_bounds__(256, 4) void conv_transpose3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int K_dyn,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int dilD, int dilH, int dilW,
    int groups,
    int icChunk,
    int Dout, int Hout, int Wout)
{
  const int K = (KC > 0) ? KC : K_dyn;
  constexpr int Threads = 256;
  constexpr int PVec    = 2;
  constexpr int OcTile  = 6;

  const int Cin_per_group  = Cin / groups;
  const int Cout_per_group = Cout / groups;
  const int oc_tiles_per_group = (Cout_per_group + OcTile - 1) / OcTile;

  const int tid = threadIdx.x;
  const int n   = blockIdx.z;

  const int oc_tile_global   = blockIdx.y;
  const int g                = oc_tile_global / oc_tiles_per_group;
  const int oc_tile_in_group = oc_tile_global % oc_tiles_per_group;

  const int P_total = Dout * Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  const int KKK = K * K * K;

  // --- Global tensors via CUTE ---
  const int64_t sXn = (int64_t)Cin * D * H * Win;
  const int64_t sXc = (int64_t)D * H * Win;
  const int64_t sXd = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                         make_shape(Cin, D, H, Win),
                         make_stride(sXc, sXd, sXh, Int<1>{}));

  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                         make_shape(Cout, Dout, Hout, Wout),
                         make_stride(sYc, sYd, sYh, Int<1>{}));

  // Weight layout: (Cin, Cout_per_group, KKK) contiguous
  auto mW = make_tensor(make_gmem_ptr(W),
                         make_shape(Cin, Cout_per_group, KKK),
                         make_stride((int64_t)Cout_per_group * KKK, (int64_t)KKK, (int64_t)1));

  // --- Shared memory: cache a bounded chunk of input channels (icChunk of
  // them at a time) x OcTile output channels x all kernel taps. Bounding the
  // chunk size (rather than caching all of Cin_per_group at once) keeps the
  // dynamic shared memory request within the device's opt-in shared-memory
  // limit regardless of how large Cin_per_group is. We loop over chunks of
  // the input-channel dimension below, doing one cooperative load + sync per
  // chunk instead of a single unbounded load.
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  auto sW = make_tensor(make_smem_ptr(sW_ptr),
                         make_shape(icChunk, OcTile, KKK),
                         make_stride((int64_t)OcTile * KKK, (int64_t)KKK, (int64_t)1));
  // Precompute output coordinates for the PVec elements handled by this thread
  int p_idx[PVec];
  int od_arr[PVec], oh_arr[PVec], ow_arr[PVec];
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      int od = p / (Hout * Wout);
      int rem = p - od * (Hout * Wout);
      int oh = rem / Wout;
      int ow = rem - oh * Wout;
      od_arr[i] = od;
      oh_arr[i] = oh;
      ow_arr[i] = ow;
    } else {
      od_arr[i] = 0; oh_arr[i] = 0; ow_arr[i] = 0;
    }
  }
  // Accumulators
  float acc[OcTile][PVec];
  #pragma unroll
  for (int oc_off = 0; oc_off < OcTile; ++oc_off) {
    int oc_local = oc_tile_in_group * OcTile + oc_off;
    int oc_global = g * Cout_per_group + oc_local;
    float bval = 0.0f;
    if (Bias != nullptr && oc_local < Cout_per_group) {
      bval = (float)Bias[oc_global];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[oc_off][i] = bval;
    }
  }
  const int ic_start = g * Cin_per_group;
  const int numIc    = Cin_per_group;
  // Process input channels in bounded chunks that fit into shared memory,
  // rather than caching the entire (unbounded) Cin_per_group range at once.
  for (int chunk_start = 0; chunk_start < numIc; chunk_start += icChunk) {
    const int chunk_size = (numIc - chunk_start < icChunk) ? (numIc - chunk_start) : icChunk;
    const int totElts = chunk_size * OcTile * KKK;
    for (int idx = tid; idx < totElts; idx += Threads) {
      int ic_local = idx / (OcTile * KKK);
      int rem = idx - ic_local * (OcTile * KKK);
      int oc_off = rem / KKK;
      int kkk = rem - oc_off * KKK;
      int ic = ic_start + chunk_start + ic_local;
      int oc_local = oc_tile_in_group * OcTile + oc_off;
      T wval = T(0);
      if (oc_local < Cout_per_group) {
        wval = mW(ic, oc_local, kkk);
      }
      sW(ic_local, oc_off, kkk) = wval;
    }
    __syncthreads();
    for (int i0 = 0; i0 < chunk_size; ++i0) {
      int ic = ic_start + chunk_start + i0;
#pragma unroll
      for (int kd = 0; kd < K; ++kd) {
#pragma unroll
        for (int kh = 0; kh < K; ++kh) {
#pragma unroll
          for (int kw = 0; kw < K; ++kw) {
            int kkk = (kd * K + kh) * K + kw;
            // Hoist the weight values for this (i0, kkk) tap into registers
            // once, and reuse them across all PVec output points handled by
            // this thread instead of re-reading shared memory per point.
            float wreg[OcTile];
            #pragma unroll
            for (int oc_off = 0; oc_off < OcTile; ++oc_off) {
              wreg[oc_off] = (float)sW(i0, oc_off, kkk);
            }
            #pragma unroll
            for (int i = 0; i < PVec; ++i) {
              int p = p_idx[i];
              if (p >= P_total) continue;
              int od = od_arr[i];
              int oh = oh_arr[i];
              int ow = ow_arr[i];
              int num_d = od + padD - kd * dilD;
