class ModelNew(nn.Module):
    """
    Transposed 3D convolution implemented with a single custom CUTE/CUDA kernel.
    Parameters are stored/initialized via nn.ConvTranspose3d (for exact parity with
    PyTorch's default initialization), but the forward pass uses our custom kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        # Keep a reference module purely for parameter storage & standard init
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels, (kernel_size, kernel_size, kernel_size),
            stride=stride, padding=padding, output_padding=output_padding,
            dilation=dilation, groups=groups, bias=bias
        )

        self.stride = int(stride)
        self.padding = int(padding)
        self.output_padding = int(output_padding)
        self.dilation = int(dilation)
        self.groups = int(groups)
        self._ext = conv_t3d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        weight = self.conv_transpose3d.weight
        bias = self.conv_transpose3d.bias
        return self._ext.conv_transpose3d_forward(
            x.contiguous(),
            weight.contiguous(),
            bias if bias is not None else None,
            self.stride,
            self.padding,
            self.output_padding,
            self.dilation,
            self.groups,
        )

