import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_forward(torch::Tensor x,
                                        torch::Tensor weight,
                                        c10::optional<torch::Tensor> bias,
                                        int stride, int padding, int output_padding,
                                        int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T, int KC>
__global__ void conv_transpose3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int K_dyn,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int dilD, int dilH, int dilW,
    int groups,
    int icChunk,
    int Dout, int Hout, int Wout)
{
  const int K = (KC > 0) ? KC : K_dyn;
  constexpr int Threads = 256;
  constexpr int PVec    = 2;
  constexpr int OcTile  = 24;

  const int Cin_per_group  = Cin / groups;
  const int Cout_per_group = Cout / groups;
  const int oc_tiles_per_group = (Cout_per_group + OcTile - 1) / OcTile;

  const int tid = threadIdx.x;
  const int n   = blockIdx.z;

  const int oc_tile_global   = blockIdx.y;
  const int g                = oc_tile_global / oc_tiles_per_group;
  const int oc_tile_in_group = oc_tile_global % oc_tiles_per_group;

  const int P_total = Dout * Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  const int KKK = K * K * K;

  // --- Global tensors via CUTE ---
  const int64_t sXn = (int64_t)Cin * D * H * Win;
  const int64_t sXc = (int64_t)D * H * Win;
  const int64_t sXd = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                         make_shape(Cin, D, H, Win),
                         make_stride(sXc, sXd, sXh, Int<1>{}));

  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                         make_shape(Cout, Dout, Hout, Wout),
                         make_stride(sYc, sYd, sYh, Int<1>{}));

  // Weight layout: (Cin, Cout_per_group, KKK) contiguous
  auto mW = make_tensor(make_gmem_ptr(W),
                         make_shape(Cin, Cout_per_group, KKK),
                         make_stride((int64_t)Cout_per_group * KKK, (int64_t)KKK, (int64_t)1));

  // --- Shared memory: cache a bounded chunk of input channels (icChunk of
  // them at a time) x OcTile output channels x all kernel taps. Bounding the
  // chunk size (rather than caching all of Cin_per_group at once) keeps the
  // dynamic shared memory request within the device's opt-in shared-memory
  // limit regardless of how large Cin_per_group is. We loop over chunks of
  // the input-channel dimension below, doing one cooperative load + sync per
  // chunk instead of a single unbounded load.
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  auto sW = make_tensor(make_smem_ptr(sW_ptr),
                         make_shape(icChunk, OcTile, KKK),
                         make_stride((int64_t)OcTile * KKK, (int64_t)KKK, (int64_t)1));
  // Precompute output coordinates for the PVec elements handled by this thread
  int p_idx[PVec];
  int od_arr[PVec], oh_arr[PVec], ow_arr[PVec];
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      int od = p / (Hout * Wout);
      int rem = p - od * (Hout * Wout);
      int oh = rem / Wout;
      int ow = rem - oh * Wout;
      od_arr[i] = od;
      oh_arr[i] = oh;
      ow_arr[i] = ow;
    } else {
      od_arr[i] = 0; oh_arr[i] = 0; ow_arr[i] = 0;
    }
  }
  // Accumulators
  float acc[OcTile][PVec];
  #pragma unroll
  for (int oc_off = 0; oc_off < OcTile; ++oc_off) {
    int oc_local = oc_tile_in_group * OcTile + oc_off;
    int oc_global = g * Cout_per_group + oc_local;
    float bval = 0.0f;
    if (Bias != nullptr && oc_local < Cout_per_group) {
      bval = (float)Bias[oc_global];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[oc_off][i] = bval;
    }
  }
  const int ic_start = g * Cin_per_group;
  const int numIc    = Cin_per_group;
  // Process input channels in bounded chunks that fit into shared memory,
  // rather than caching the entire (unbounded) Cin_per_group range at once.
  for (int chunk_start = 0; chunk_start < numIc; chunk_start += icChunk) {
    const int chunk_size = (numIc - chunk_start < icChunk) ? (numIc - chunk_start) : icChunk;
    const int totElts = chunk_size * OcTile * KKK;
    for (int idx = tid; idx < totElts; idx += Threads) {
      int ic_local = idx / (OcTile * KKK);
      int rem = idx - ic_local * (OcTile * KKK);
      int oc_off = rem / KKK;
      int kkk = rem - oc_off * KKK;
      int ic = ic_start + chunk_start + ic_local;
      int oc_local = oc_tile_in_group * OcTile + oc_off;
      T wval = T(0);
      if (oc_local < Cout_per_group) {
        wval = mW(ic, oc_local, kkk);
      }
      sW(ic_local, oc_off, kkk) = wval;
    }
    __syncthreads();
    for (int i0 = 0; i0 < chunk_size; ++i0) {
      int ic = ic_start + chunk_start + i0;
      #pragma unroll
      for (int i = 0; i < PVec; ++i) {
        int p = p_idx[i];
        if (p >= P_total) continue;
        int od = od_arr[i];
        int oh = oh_arr[i];
        int ow = ow_arr[i];
#pragma unroll
        for (int kd = 0; kd < K; ++kd) {
          int num_d = od + padD - kd * dilD;
          if (num_d % strideD != 0) continue;
          int id = num_d / strideD;
          if (id < 0 || id >= D) continue;
#pragma unroll
          for (int kh = 0; kh < K; ++kh) {
            int num_h = oh + padH - kh * dilH;
            if (num_h % strideH != 0) continue;
            int ih = num_h / strideH;
            if (ih < 0 || ih >= H) continue;
#pragma unroll
            for (int kw = 0; kw < K; ++kw) {
              int num_w = ow + padW - kw * dilW;
              if (num_w % strideW != 0) continue;
              int iw = num_w / strideW;
              if (iw < 0 || iw >= Win) continue;
              int kkk = (kd * K + kh) * K + kw;
              float xval = (float)mX(ic, id, ih, iw);
              #pragma unroll
              for (int oc_off = 0; oc_off < OcTile; ++oc_off) {
                float wval = (float)sW(i0, oc_off, kkk);
                acc[oc_off][i] += xval * wval;
              }
            }
          }
        }
      }
    }
    __syncthreads();
  }

  // Store results
  #pragma unroll
  for (int oc_off = 0; oc_off < OcTile; ++oc_off) {
    int oc_local = oc_tile_in_group * OcTile + oc_off;
    if (oc_local >= Cout_per_group) continue;
    int oc_global = g * Cout_per_group + oc_local;

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      mY(oc_global, od_arr[i], oh_arr[i], ow_arr[i]) = static_cast<T>(acc[oc_off][i]);
    }
  }
}

torch::Tensor conv_transpose3d_forward(torch::Tensor x,
                                        torch::Tensor weight,
                                        c10::optional<torch::Tensor> bias,
                                        int stride, int padding, int output_padding,
                                        int dilation, int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be [N, C, D, H, W]");
  TORCH_CHECK(weight.dim() == 5, "weight must be [Cin, Cout/groups, K, K, K]");

  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t D   = x.size(2);
  int64_t H   = x.size(3);
  int64_t Win = x.size(4);

  int64_t Cout_per_group = weight.size(1);
  int64_t K = weight.size(2);
  TORCH_CHECK(weight.size(0) == Cin, "weight.size(0) must equal Cin");
  TORCH_CHECK(weight.size(3) == K && weight.size(4) == K, "kernel must be cubic");

  int64_t Cout = Cout_per_group * groups;
  int64_t Cin_per_group = Cin / groups;

  TORCH_CHECK(stride > 0 && dilation > 0, "stride/dilation must be > 0");
  TORCH_CHECK(padding >= 0 && output_padding >= 0, "padding/output_padding must be >= 0");

  int64_t Dout = (D - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
  int64_t Hout = (H - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
  int64_t Wout = (Win - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());

  constexpr int Threads = 256;
  constexpr int PVec    = 2;
  constexpr int OcTile  = 24;

  int64_t P_total = Dout * Hout * Wout;
  int64_t PTile   = Threads * PVec;

  int oc_tiles_per_group = (int)((Cout_per_group + OcTile - 1) / OcTile);
  int grid_y = groups * oc_tiles_per_group;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)grid_y,
      (unsigned)N
  );

  int device = 0;
  cudaGetDevice(&device);
  int max_smem_optin = 0;
  cudaDeviceGetAttribute(&max_smem_optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, device);
  size_t smem_budget = (size_t)((max_smem_optin > 0 ? max_smem_optin : 48 * 1024) * 0.9);
  size_t per_ic_bytes = (size_t)OcTile * (size_t)K * (size_t)K * (size_t)K * sizeof(float);
  int icChunk = (int)(smem_budget / (per_ic_bytes > 0 ? per_ic_bytes : 1));
  if (icChunk < 1) icChunk = 1;
  if (icChunk > (int)Cin_per_group) icChunk = (int)Cin_per_group;
  size_t shmem_bytes = (size_t)icChunk * OcTile * K * K * K * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (K == 3) {
    if (shmem_bytes > 48 * 1024) {
      cudaError_t attr_status = cudaFuncSetAttribute(
          conv_transpose3d_kernel<float, 3>,
          cudaFuncAttributeMaxDynamicSharedMemorySize,
          (int)shmem_bytes);
      TORCH_CHECK(attr_status == cudaSuccess,
                  "cudaFuncSetAttribute failed: ", cudaGetErrorString(attr_status));
    }
    conv_transpose3d_kernel<float, 3><<<grid, block, shmem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        (int)N, (int)Cin, (int)D, (int)H, (int)Win,
        (int)Cout, (int)K,
        stride, stride, stride,
        padding, padding, padding,
        dilation, dilation, dilation,
        groups,
        icChunk,
        (int)Dout, (int)Hout, (int)Wout
    );
  } else {
    if (shmem_bytes > 48 * 1024) {
      cudaError_t attr_status = cudaFuncSetAttribute(
          conv_transpose3d_kernel<float, 0>,
          cudaFuncAttributeMaxDynamicSharedMemorySize,
          (int)shmem_bytes);
      TORCH_CHECK(attr_status == cudaSuccess,
                  "cudaFuncSetAttribute failed: ", cudaGetErrorString(attr_status));
    }
    conv_transpose3d_kernel<float, 0><<<grid, block, shmem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        (int)N, (int)Cin, (int)D, (int)H, (int)Win,
        (int)Cout, (int)K,
        stride, stride, stride,
        padding, padding, padding,
        dilation, dilation, dilation,
        groups,
        icChunk,
        (int)Dout, (int)Hout, (int)Wout
    );
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

